<?php
use EIPSI\ExternalApi as A;
function b_create($k,$p=null,$format='json',$partials=false){$api=new A\DatasetSnapshots();return $api->create($k['principal'],($p??$GLOBALS['p'])['public'],array('format'=>$format,'include_partials'=>$partials));}
function b_ready($k,$r){$api=new A\DatasetSnapshots();$storage=new A\ExportStorage();for($i=0;$i<1000;$i++){$status=$storage->get($r['export_id']);if($status['state']!=='PREPARING'){$status=$api->status($k['principal'],$r['export_id']);d2_assert($status['status']==='READY','Export '.$status['status'].' '.($status['error_code']??''));return$status;}$api->work($r['export_id']);}throw new RuntimeException('Worker stalled');}
function b_content($k,$r,$range=null){$d=(new A\DatasetSnapshots())->download($k['principal'],$r['export_id'],$range);try{return fread($d->stream,$d->length?:1);}finally{$d->close();}}
function b_data($k,$r,$params=array()){return(new A\DatasetSnapshots())->data($k['principal'],$r['export_id'],$params);}
function b_case($name,$fn){d2_case($name,$fn);}
b_case('Create returns opaque PREPARING export with stable as_of',function(){$k=d2_key();$r=b_create($k);d2_assert($r['status']==='PREPARING'&&preg_match('/^[a-f0-9]{32}$/D',$r['export_id'])&&$r['dataset_contract']==='EIPSI_STUDY_DATA_V1');$GLOBALS['b_main']=array($k,$r);});
b_case('Worker reaches READY and snapshot equals API2A and Management',function(){[$k,$r]=$GLOBALS['b_main'];$ready=b_ready($k,$r);d2_assert($ready['as_of']===$r['as_of']);d2_parity(b_data($k,$r)['items'],d2_read($k)['items']);d2_parity(b_data($k,$r)['items'],d2_management($GLOBALS['p']));$api=new A\DatasetSnapshots();file_put_contents('/tmp/eipsi-api2b-examples.json',json_encode(array('synthetic_fixture'=>true,'create'=>$r,'ready'=>$ready,'page'=>b_data($k,$r),'manifest'=>$api->manifest($k['principal'],$r['export_id']),'dictionary'=>$api->dictionary($k['principal'],$r['export_id'])),JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));});
b_case('New responses stay out of S1 and enter S2',function(){[$k,$r]=$GLOBALS['b_main'];$before=b_data($k,$r);d2_finish($GLOBALS['p'],'NEW_AFTER_S1');d2_assert(b_data($k,$r)===$before);$s=b_ready($k,b_create($k));d2_assert(count(b_data($k,$s)['items'])===2);});
b_case('CSV SEC1 bytes equal API2A including header',function(){$k=d2_key();$r=b_ready($k,b_create($k,null,'csv'));d2_assert(b_content($k,$r)===d2_read($k,array('format'=>'csv'))['csv']);$GLOBALS['b_csv']=array($k,$r);});
b_case('Manifest SHA256 verifies repeatable complete download',function(){[$k,$r]=$GLOBALS['b_csv'];$m=(new A\DatasetSnapshots())->manifest($k['principal'],$r['export_id']);$bytes=b_content($k,$r);d2_assert(hash('sha256',$bytes)===$m['sha256']&&strlen($bytes)===$m['byte_count']&&$bytes===b_content($k,$r));});
b_case('Download supports prefix suffix and open byte Ranges',function(){[$k,$r]=$GLOBALS['b_csv'];$all=b_content($k,$r);foreach(array('bytes=0-19'=>substr($all,0,20),'bytes=-20'=>substr($all,-20),'bytes=20-'=>substr($all,20))as$range=>$expected)d2_assert(b_content($k,$r,$range)===$expected);});
b_case('Invalid and multipart Ranges fail with 416',function(){[$k,$r]=$GLOBALS['b_csv'];foreach(array('bytes=2-1','bytes=999999999-','bytes=0-1,3-4','bytes=-0','items=0-1','bytes=-')as$range)d2_error(function()use($k,$r,$range){b_content($k,$r,$range);},416,'eipsi_external_invalid_range');});
b_case('Dictionary is frozen and corresponds to API2A',function(){[$k,$r]=$GLOBALS['b_main'];$d=(new A\DatasetSnapshots())->dictionary($k['principal'],$r['export_id']);d2_assert($d['items']===d2_read($k,array(),null,true)['items']&&$d['as_of']===$r['as_of']);});
b_case('Another key with same Study cannot read export',function(){[$owner,$r]=$GLOBALS['b_main'];$k=d2_key();$api=new A\DatasetSnapshots();foreach(array('status','manifest','dictionary','download')as$m)d2_error(function()use($api,$k,$r,$m){$api->$m($k['principal'],$r['export_id']);},404,'eipsi_external_export_unavailable');$none=d2_key(array(),array('read:data'),'NONE');foreach(array($r['export_id'],str_repeat('f',32))as$id)d2_error(function()use($api,$none,$id){$api->status($none['principal'],$id);},404,'eipsi_external_export_unavailable');});
b_case('Snapshot pages have no duplicates and preserve as_of',function(){[$k,$r]=$GLOBALS['b_csv'];$all=array();$cursor=null;do{$params=array('limit'=>1);if($cursor!==null)$params['cursor']=$cursor;$page=b_data($k,$r,$params);d2_assert($page['as_of']===$r['as_of']);$all=array_merge($all,$page['items']);$cursor=$page['next_cursor'];}while($cursor!==null);d2_assert(count($all)===2);});
b_case('Snapshot cursor rejects cross-key export and live audience',function(){[$k,$r]=$GLOBALS['b_csv'];$cursor=b_data($k,$r,array('limit'=>1))['next_cursor'];$s=b_ready($k,b_create($k));d2_error(function()use($k,$s,$cursor){b_data($k,$s,array('cursor'=>$cursor));},400,'eipsi_external_invalid_cursor');$bad=(new A\Cursor())->encode($k['key']['id'],'A','Z');d2_error(function()use($k,$r,$bad){b_data($k,$r,array('cursor'=>$bad));},400,'eipsi_external_invalid_cursor');});
foreach(array('../','a/b',"\0",'ｅ１２',str_repeat('a',33))as$i=>$id)b_case('Path and identifier input rejected '.$i,function()use($id){d2_error(function()use($id){(new A\DatasetSnapshots())->status(d2_key()['principal'],$id);},404,'eipsi_external_export_unavailable');});
foreach(array('revoke','scope','grant')as$change)b_case('Delivery revalidates '.$change,function()use($change){$k=d2_key();$r=b_ready($k,b_create($k));$id=$GLOBALS['p']['definition']['study']['logical_id'];if($change==='revoke')$GLOBALS['keys']->revoke($k['key']['id'],1,1,A\Authenticator::requestId());else$GLOBALS['keys']->update($k['key']['id'],1,array('name'=>'Changed','scopes'=>array($change==='scope'?'read:studies':'read:data'),'grant_mode'=>$change==='grant'?'NONE':'SELECTED','studies'=>$change==='grant'?array():array($id),'expires_at'=>null),1,A\Authenticator::requestId());foreach(array('status','manifest','dictionary','download','data')as$operation)d2_error(function()use($k,$r,$operation){(new A\DatasetSnapshots())->$operation($k['principal'],$r['export_id'],...($operation==='data'?array(array()):array()));},$change==='revoke'?401:($change==='scope'?403:404),$change==='revoke'?'eipsi_external_unauthorized':($change==='scope'?'eipsi_external_scope_denied':'eipsi_external_export_unavailable'));});
b_case('Expiry denies new downloads and cleanup is idempotent',function(){[$k,$r]=$GLOBALS['b_csv'];$api=new A\DatasetSnapshots(static function()use($r){return strtotime($r['expires_at'])+1;});d2_assert($api->status($k['principal'],$r['export_id'])['status']==='EXPIRED');d2_error(function()use($api,$k,$r){$api->download($k['principal'],$r['export_id']);},410,'eipsi_external_export_expired');$storage=new A\ExportStorage();$storage->cleanup(strtotime($r['expires_at'])+1,50);$storage->cleanup(strtotime($r['expires_at'])+1,50);d2_assert(iterator_to_array($storage->chunks($r['export_id'],'download'))===array());});
b_case('DO_NOT_USE revokes entire previously READY export',function(){$p=d2_publish(true);$f=d2_finish($p,'WITHDRAW_ME');$k=d2_key(array($p['definition']['study']['logical_id']));$r=b_ready($k,b_create($k,$p));d2_withdraw($f['frame'],'DO_NOT_USE');d2_assert((new A\DatasetSnapshots())->status($k['principal'],$r['export_id'])['status']==='REVOKED');d2_error(function()use($k,$r){b_content($k,$r);},410,'eipsi_external_snapshot_invalidated');$s=new A\Store();$audit=$s->row($s->prepare("SELECT details_json FROM ".$s->table('audit')." WHERE key_id=%s AND event='EXPORT_REVOKED'",$k['key']['id']));d2_assert(json_decode($audit['details_json'],true)['export_id']===$r['export_id']);});
b_case('Hard delete Study denies exports without ghost content',function(){$p=d2_publish();d2_finish($p);$id=$p['definition']['study']['logical_id'];$k=d2_key(array($id));$r=b_ready($k,b_create($k,$p));$GLOBALS['builder']->deleteStudy($id,'ELIMINAR '.$id);d2_error(function()use($k,$r){b_content($k,$r);},404,'eipsi_external_export_unavailable');});
b_case('Changed mutable source fails rather than mixing values',function(){$p=d2_publish();$f=d2_finish($p,'BEFORE');$k=d2_key(array($p['definition']['study']['logical_id']));$r=b_create($k,$p);$db=pf_db();$db->query($db->prepare('UPDATE '.$db->table('study_executions').' SET revision=revision+1 WHERE id=%s',$f['frame']['access']['execution_id']));(new A\DatasetSnapshots())->work($r['export_id']);d2_assert((new A\DatasetSnapshots())->status($k['principal'],$r['export_id'])['status']==='FAILED');});
b_case('Lease expiry recovers after manifest and duplicate steps cannot duplicate rows',function(){$k=d2_key();$r=b_create($k);$store=new A\Store();$store->rows($store->prepare('UPDATE '.$store->table('exports').' SET lease_token=%s,lease_until=%d WHERE id=%s',str_repeat('a',32),time()+60,$r['export_id']));$api=new A\DatasetSnapshots();d2_assert(!$api->work($r['export_id']));$store->rows($store->prepare('UPDATE '.$store->table('exports').' SET lease_until=0 WHERE id=%s',$r['export_id']));$r=b_ready($k,$r);d2_assert(!$api->work($r['export_id'])&&count(b_data($k,$r)['items'])===2);});
b_case('Stored byte corruption is detected before download',function(){$k=d2_key();$r=b_ready($k,b_create($k));$s=new A\Store();$s->rows($s->prepare("UPDATE ".$s->table('export_chunks')." SET payload=CONCAT('x',payload) WHERE export_id=%s AND kind='download' AND sequence=1",$r['export_id']));d2_error(function()use($k,$r){b_content($k,$r);},503,'eipsi_external_export_failed');});
b_case('Per-key PREPARING quota rejects third concurrent export',function(){$k=d2_key();b_create($k);b_create($k);d2_error(function()use($k){b_create($k);},429,'eipsi_external_export_quota');});
function b_http($k,$route,$method='GET',$body=null,$headers=array()){$h=array('Host'=>'127.0.0.1:18080');if($k)$h['Authorization']='Bearer '.$k['secret'];$args=array('method'=>$method,'timeout'=>30,'headers'=>array_merge($h,$headers));if($body!==null){$args['headers']['Content-Type']='application/json';$args['body']=json_encode($body);}$r=wp_remote_request('http://127.0.0.1/?rest_route='.rawurlencode('/eipsi-external/v1/'.$route),$args);d2_assert(!is_wp_error($r));return array('status'=>wp_remote_retrieve_response_code($r),'body'=>wp_remote_retrieve_body($r),'data'=>json_decode(wp_remote_retrieve_body($r),true),'headers'=>wp_remote_retrieve_headers($r));}
b_case('HTTP POST creates export and status polling recovers missed cron',function(){$k=d2_key();$r=b_http($k,'studies/'.$GLOBALS['p']['public'].'/exports','POST',array('format'=>'csv'));d2_assert($r['status']===202&&$r['data']['status']==='PREPARING'&&$r['headers']['retry-after']==='5');$id=$r['data']['export_id'];for($i=0;$i<6;$i++){$r=b_http($k,'exports/'.$id);if($r['data']['status']==='READY')break;}d2_assert($r['data']['status']==='READY');$GLOBALS['b_http']=array($k,$r['data']);});
b_case('HTTP download and Range are raw bytes with private safe headers',function(){[$k,$r]=$GLOBALS['b_http'];$all=b_http($k,'exports/'.$r['export_id'].'/download');d2_assert($all['status']===200&&strpos($all['body'],'study_code,study_id')===0&&$all['headers']['content-length']===(string)strlen($all['body'])&&strpos($all['headers']['cache-control'],'no-store')!==false&&$all['headers']['x-content-type-options']==='nosniff'&&strpos($all['headers']['content-disposition'],'attachment; filename="eipsi-export-')===0);$part=b_http($k,'exports/'.$r['export_id'].'/download','GET',null,array('Range'=>'bytes=0-19'));d2_assert($part['status']===206&&$part['body']===substr($all['body'],0,20)&&$part['headers']['content-range']==='bytes 0-19/'.strlen($all['body']));$mismatch=b_http($k,'exports/'.$r['export_id'].'/download','GET',null,array('Range'=>'bytes=0-19','If-Range'=>'"different"'));d2_assert($mismatch['status']===200&&$mismatch['body']===$all['body']);$match=b_http($k,'exports/'.$r['export_id'].'/download','GET',null,array('Range'=>'bytes=0-19','If-Range'=>$all['headers']['etag']));d2_assert($match['status']===206&&strlen($match['body'])===20);$invalid=b_http($k,'exports/'.$r['export_id'].'/download','GET',null,array('Range'=>'bytes=999999999-'));d2_assert($invalid['status']===416&&$invalid['headers']['content-range']==='bytes */'.strlen($all['body']));});
b_case('HTTP JSON manifest dictionary and snapshot pages share as_of',function(){[$k,$r]=$GLOBALS['b_http'];foreach(array('manifest','dictionary','data')as$suffix){$x=b_http($k,'exports/'.$r['export_id'].'/'.$suffix);d2_assert($x['status']===200&&$x['data']['as_of']===$r['as_of']);}});
b_case('Every export HTTP endpoint is Bearer-only',function(){[$k,$r]=$GLOBALS['b_http'];foreach(array('','/manifest','/dictionary','/download','/data')as$suffix)d2_assert(b_http(null,'exports/'.$r['export_id'].$suffix)['status']===401);d2_assert(b_http(null,'studies/'.$GLOBALS['p']['public'].'/exports','POST',array('format'=>'json'))['status']===401);});
b_case('Include partials is immutable and changed saved value requires S2',function(){ $p=d2_publish(true);$f=pf_enroll($p);$block=$f['view']['next_action']['payload']['assessment_execution_id'];$graph=(new EIPSI\StudyEngine\Persistence\StudyVersionRepository(pf_db()))->compiled((new EIPSI\StudyEngine\Persistence\StudyVersionRepository(pf_db()))->find($p['version']));$decode=function($value)use($p,$graph,$f,$block){return(new EIPSI\StudyEngine\Content\ResponseAdapter())->decode($p['definition'],array('R_q1'=>$value),$graph->descendants($f['view']['snapshot']['instances'][$block]['definition_id']));};pf_dispatch($f,'SAVE_PAGE',array('block_execution_id'=>$block,'responses'=>$decode('ORIGINAL_PARTIAL')));$k=d2_key(array($p['definition']['study']['logical_id']));$s1=b_ready($k,b_create($k,$p,'json',true));$none=b_ready($k,b_create($k,$p));d2_assert(count(b_data($k,$none)['items'])===0);pf_dispatch($f,'SAVE_PAGE',array('block_execution_id'=>$block,'responses'=>$decode('UPDATED_PARTIAL')));$s2=b_ready($k,b_create($k,$p,'json',true));d2_assert(b_data($k,$s1)['items'][0]['value']==='ORIGINAL_PARTIAL'&&b_data($k,$s2)['items'][0]['value']==='UPDATED_PARTIAL');});
b_case('Study V2 enters only newly requested snapshot',function(){$p=d2_publish();d2_finish($p,'V1');$k=d2_key(array($p['definition']['study']['logical_id']));$s1=b_ready($k,b_create($k,$p));$d=pe_definition('simple',$p['definition']['study']['logical_id'],$p['public'],2);$v2=d2_publish(false,$d);d2_finish($v2,'V2');$s2=b_ready($k,b_create($k,$p));d2_assert(count(b_data($k,$s1)['items'])===1&&count(b_data($k,$s2)['items'])===2);});
b_case('Native typed answers and historical dictionary preserve parity',function(){$n=d2_native();$p=$n['p'];$k=d2_key(array($p['definition']['study']['logical_id']));$r=b_ready($k,b_create($k,$p));d2_parity(b_data($k,$r)['items'],d2_read($k,array(),$p)['items']);$dictionary=(new A\DatasetSnapshots())->dictionary($k['principal'],$r['export_id']);d2_assert($dictionary['items']===d2_read($k,array(),$p,true)['items']);});
b_case('Native randomization exclusion and null scientific statuses preserve parity',function(){$n=d2_native(true,true);$p=$n['p'];$k=d2_key(array($p['definition']['study']['logical_id']));$r=b_ready($k,b_create($k,$p));$rows=b_data($k,$r)['items'];d2_parity($rows,d2_read($k,array(),$p)['items']);d2_assert(count(array_filter($rows,static function($x){return$x['response_status']==='NOT_SELECTED_BY_RANDOMIZATION';}))===1);});
b_case('Pause and archive do not revoke a READY snapshot',function(){$p=d2_publish();d2_finish($p);$k=d2_key(array($p['definition']['study']['logical_id']));$r=b_ready($k,b_create($k,$p));$pending=b_create($k,$p);$builder=$GLOBALS['builder'];$s=$builder->load($p['version']);$builder->changeStudyState($s['id'],$s['lifecycle']['revision'],'PAUSED',false,'API2B_PAUSE');$s=$builder->load($p['version']);$builder->archiveStudy($s['id'],$s['revision']);d2_assert(count(b_data($k,$r)['items'])===1);$prepared=b_ready($k,$pending);d2_assert(count(b_data($k,$prepared)['items'])===1);});
b_case('ALL to SELECTED without Study blocks subsequent requests',function(){$k=d2_key(array(),array('read:data'),'ALL');$r=b_ready($k,b_create($k));$GLOBALS['keys']->update($k['key']['id'],1,array('name'=>'Selected','scopes'=>array('read:data'),'grant_mode'=>'SELECTED','studies'=>array(),'expires_at'=>null),1,A\Authenticator::requestId());d2_error(function()use($k,$r){b_data($k,$r);},404,'eipsi_external_export_unavailable');});
b_case('Disabled API blocks previously authenticated export owner',function(){$k=d2_key();$r=b_ready($k,b_create($k));$s=new A\Store();$s->setEnabled(false,1,A\Authenticator::requestId(),time());try{d2_error(function()use($k,$r){b_content($k,$r);},404,'eipsi_external_unavailable');}finally{$s->setEnabled(true,1,A\Authenticator::requestId(),time());}});
b_case('DO_NOT_USE before materialization revokes PREPARING and participant cleanup keeps it revoked',function(){$p=d2_publish(true);$f=d2_finish($p);$k=d2_key(array($p['definition']['study']['logical_id']));$r=b_create($k,$p);d2_withdraw($f['frame'],'DO_NOT_USE');EIPSI_Privacy_Data_Cleanup_Service::run_study_engine(pf_db(),$f['frame']['access']['execution_id']);d2_assert(!(new A\DatasetSnapshots())->work($r['export_id'])&&(new A\DatasetSnapshots())->status($k['principal'],$r['export_id'])['status']==='REVOKED');});
b_case('Active download handle survives cleanup and later expired request fails',function(){$k=d2_key();$r=b_ready($k,b_create($k));$api=new A\DatasetSnapshots();$d=$api->download($k['principal'],$r['export_id']);$storage=new A\ExportStorage();$storage->cleanup(strtotime($r['expires_at'])+400,50);try{$bytes=fread($d->stream,$d->length);d2_assert(strlen($bytes)===$d->total&&hash('sha256',$bytes)===$d->sha256);}finally{$d->close();}d2_error(function()use($k,$r){b_content($k,$r);},410,'eipsi_external_export_expired');});
b_case('Cleanup defers deletion while a live download reference is active',function(){$k=d2_key();$r=b_ready($k,b_create($k));$s=new A\Store();$s->rows($s->prepare("UPDATE ".$s->table('exports')." SET state='REVOKED',download_until=%d WHERE id=%s",time()+120,$r['export_id']));$storage=new A\ExportStorage();$storage->cleanup(time(),50);d2_assert(count(iterator_to_array($storage->chunks($r['export_id'],'download')))>0);$s->rows($s->prepare('UPDATE '.$s->table('exports').' SET download_until=0 WHERE id=%s',$r['export_id']));$storage->cleanup(time(),50);d2_assert(iterator_to_array($storage->chunks($r['export_id'],'download'))===array());});
b_case('Malformed creation filters never create resources',function(){$k=d2_key();foreach(array(array(),array('format'=>'xlsx'),array('format'=>'json','include_partials'=>'false'),array('format'=>'json','include_partials'=>null),array('format'=>'json','unknown'=>true))as$body)d2_error(function()use($k,$body){(new A\DatasetSnapshots())->create($k['principal'],$GLOBALS['p']['public'],$body);},400,'eipsi_external_invalid_filters');});
b_case('Snapshot data rejects filter mutation and malformed cursors',function(){$k=d2_key();$r=b_ready($k,b_create($k));d2_error(function()use($k,$r){b_data($k,$r,array('include_partials'=>true));},400,'eipsi_external_invalid_filters');foreach(array('', 'd1_invalid',array(),null)as$cursor)d2_error(function()use($k,$r,$cursor){b_data($k,$r,array('cursor'=>$cursor));},400,'eipsi_external_invalid_cursor');});
b_case('Audit exposes lifecycle identifiers and counts without scientific values',function(){$k=d2_key();$r=b_ready($k,b_create($k));b_content($k,$r);$s=new A\Store();$rows=$s->rows($s->prepare("SELECT event,details_json FROM ".$s->table('audit')." WHERE key_id=%s AND LEFT(event,7)='EXPORT_'",$k['key']['id']));$events=array_column($rows,'event');foreach(array('EXPORT_CREATED','EXPORT_STARTED','EXPORT_READY','EXPORT_DOWNLOAD')as$event)d2_assert(in_array($event,$events,true));foreach($rows as$row){$data=json_decode($row['details_json'],true);d2_assert($data['export_id']===$r['export_id']&&strpos($row['details_json'],'SNAPSHOT_VALUE')===false&&strpos($row['details_json'],'@')===false);}});
b_case('Creating building and reading a snapshot never writes scientific tables',function(){ $p=d2_publish();d2_finish($p,'READONLY');$k=d2_key(array($p['definition']['study']['logical_id']));$fingerprint=function(){$db=pf_db();$out=array();foreach(array('study_versions','study_executions','block_executions','execution_events','random_decisions','participants','withdrawal_records','submission_journal','native_executions','native_versions')as$table){$rows=$db->rows('SELECT * FROM '.$db->table($table));usort($rows,static function($a,$b){return strcmp(json_encode($a),json_encode($b));});$out[$table]=hash('sha256',json_encode($rows));}global$wpdb;foreach(array('vas_form_results','eipsi_partial_responses','eipsi_device_data')as$table){$rows=$db->rows('SELECT * FROM `'.$wpdb->prefix.$table.'`');usort($rows,static function($a,$b){return strcmp(json_encode($a),json_encode($b));});$out[$table]=hash('sha256',json_encode($rows));}return$out;};$before=$fingerprint();$r=b_ready($k,b_create($k,$p));b_content($k,$r);b_data($k,$r);(new A\DatasetSnapshots())->dictionary($k['principal'],$r['export_id']);d2_assert($before===$fingerprint());});
b_case('Dataset over 10 MiB exceeds API2A but exports intact with bounded memory',function(){global$wpdb;$d=pe_definition();foreach($d['nodes']as&$node)if($node['kind']==='QUESTION')$node['validation']['max_length']=100000;unset($node);$p=d2_publish(false,$d);for($i=0;$i<145;$i++)d2_finish($p,str_repeat('z',80000));$k=d2_key(array($d['study']['logical_id']));d2_error(function()use($k,$p){d2_read($k,array('format'=>'csv'),$p);},422,'eipsi_external_export_limit_exceeded');$start=microtime(true);$q=$wpdb->num_queries;memory_reset_peak_usage();$mem=memory_get_usage();$r=b_create($k,$p,'csv');$manifestMs=(microtime(true)-$start)*1000;$manifestQueries=$wpdb->num_queries-$q;$start=microtime(true);$ready=b_ready($k,$r);$workerSeconds=microtime(true)-$start;$peak=memory_get_peak_usage()-$mem;$start=microtime(true);$download=(new A\DatasetSnapshots())->download($k['principal'],$r['export_id']);$hash=hash_init('sha256');$bytes=0;while(!feof($download->stream)){$part=fread($download->stream,65536);hash_update($hash,$part);$bytes+=strlen($part);}$download->close();$downloadSeconds=microtime(true)-$start;$manifest=(new A\DatasetSnapshots())->manifest($k['principal'],$r['export_id']);d2_assert($bytes>10485760&&$bytes===$manifest['byte_count']&&hash_final($hash)===$manifest['sha256']&&$ready['row_count']===145&&$peak<67108864);$metrics=array('fixture'=>'145 real completions, 80000 bytes each','rows'=>145,'manifest_ms'=>round($manifestMs,3),'manifest_queries'=>$manifestQueries,'worker_seconds'=>round($workerSeconds,3),'rows_per_second'=>round(145/$workerSeconds,2),'incremental_peak_bytes'=>$peak,'artifact_bytes'=>$bytes,'download_seconds'=>round($downloadSeconds,3),'download_bytes_per_second'=>round($bytes/$downloadSeconds));echo 'API2B_METRIC '.json_encode($metrics)."\n";file_put_contents('/tmp/eipsi-api2b-performance.json',json_encode($metrics,JSON_PRETTY_PRINT));});
b_case('Per-export storage ceiling produces explicit terminal too_large without truncation',function(){$k=d2_key();$r=b_create($k);$s=new A\Store();$s->rows($s->prepare('UPDATE '.$s->table('exports').' SET storage_bytes=%d WHERE id=%s',A\ExportStorage::MAX_BYTES,$r['export_id']));try{(new A\DatasetSnapshots())->work($r['export_id']);$status=(new A\DatasetSnapshots())->status($k['principal'],$r['export_id']);d2_assert($status['status']==='FAILED'&&$status['error_code']==='eipsi_external_export_too_large');d2_error(function()use($k,$r){b_content($k,$r);},409,'eipsi_external_export_failed');}finally{$s->rows($s->prepare('UPDATE '.$s->table('exports').' SET storage_bytes=0 WHERE id=%s',$r['export_id']));}});
b_case('Global capacity failure retries safely then becomes terminal and cleanable',function(){$k=d2_key();$r=b_create($k);$s=new A\Store();$anchor=b_create(d2_key());$s->rows($s->prepare('UPDATE '.$s->table('exports').' SET storage_bytes=%d WHERE id=%s',A\ExportStorage::TOTAL_BYTES,$anchor['export_id']));try{$api=new A\DatasetSnapshots();for($i=0;$i<3;$i++)$api->work($r['export_id']);d2_assert($api->status($k['principal'],$r['export_id'])['status']==='FAILED');}finally{$s->rows($s->prepare('UPDATE '.$s->table('exports').' SET storage_bytes=0 WHERE id=%s',$anchor['export_id']));}});
b_case('READY active-export quota blocks fifth resource for one key',function(){$k=d2_key();for($i=0;$i<4;$i++)b_ready($k,b_create($k));d2_error(function()use($k){b_create($k);},429,'eipsi_external_export_quota');});
b_case('Global PREPARING ceiling prevents unlimited concurrent manifests',function(){$s=new A\Store();$made=array();try{$n=(int)$s->row("SELECT COUNT(*) n FROM ".$s->table('exports')." WHERE state='PREPARING'")['n'];for($i=$n;$i<16;$i++){$k=d2_key();$made[]=b_create($k)['export_id'];}$k=d2_key();d2_error(function()use($k){b_create($k);},429,'eipsi_external_export_quota');}finally{foreach($made as$id)$s->rows($s->prepare("UPDATE ".$s->table('exports')." SET state='FAILED' WHERE id=%s",$id));(new A\ExportStorage())->cleanup(time(),50);}});
b_case('Missing JSON row chunk fails instead of silently skipping rows',function(){$k=d2_key();$r=b_ready($k,b_create($k));$s=new A\Store();$s->rows($s->prepare("DELETE FROM ".$s->table('export_chunks')." WHERE export_id=%s AND kind='rows' AND sequence=1",$r['export_id']));d2_error(function()use($k,$r){b_data($k,$r);},503,'eipsi_external_export_failed');});
b_case('Dictionary corruption fails against immutable READY checksum',function(){$k=d2_key();$r=b_ready($k,b_create($k));$s=new A\Store();$payload='[]';$s->rows($s->prepare("UPDATE ".$s->table('export_chunks')." SET payload=%s,sha256=%s,byte_count=2 WHERE export_id=%s AND kind='dictionary'",$payload,hash('sha256',$payload),$r['export_id']));d2_error(function()use($k,$r){(new A\DatasetSnapshots())->dictionary($k['principal'],$r['export_id']);},503,'eipsi_external_export_failed');});
b_case('Bounded old-metadata cleanup cannot orphan unprocessed private chunks',function(){$s=new A\Store();$made=array();for($group=0;$group<2;$group++){$k=d2_key();for($i=0;$i<6;$i++){$r=b_ready($k,b_create($k));$made[]=$r['export_id'];$s->rows($s->prepare("UPDATE ".$s->table('exports')." SET state='FAILED',expires_at=%d,download_until=0 WHERE id=%s",time()-8*A\ExportStorage::TTL,$r['export_id']));}}(new A\ExportStorage())->cleanup(time(),1);$ids=implode(',',array_map(function($id)use($s){return$s->prepare('%s',$id);},$made));$n=$s->row('SELECT COUNT(*) n FROM '.$s->table('export_chunks').' c LEFT JOIN '.$s->table('exports').' e ON e.id=c.export_id WHERE e.id IS NULL AND c.export_id IN ('.$ids.')');d2_assert((int)$n['n']===0);});
b_case('Retained B1 remains usable and preexisting B2 is absent from new snapshots',function(){$p=d2_publish(true);$a=d2_finish($p,'B1_RETAINED');$b=d2_finish($p,'B2_EXCLUDED');d2_withdraw($a['frame'],'RETAIN_FOR_ANALYSIS');d2_withdraw($b['frame'],'DO_NOT_USE');$k=d2_key(array($p['definition']['study']['logical_id']));$r=b_ready($k,b_create($k,$p));$rows=b_data($k,$r)['items'];d2_parity($rows,d2_read($k,array(),$p)['items']);d2_assert(count($rows)===1&&$rows[0]['value']==='B1_RETAINED'&&$rows[0]['data_policy']==='RETAIN_FOR_ANALYSIS');});
b_case('Native expired saved partials keep API2A eligibility states and values',function(){$n=d2_native(false);$p=$n['p'];$n['clock']->now+=86400*31;$n['owner']->view($n['id']);$k=d2_key(array($p['definition']['study']['logical_id']));$r=b_ready($k,b_create($k,$p,'json',true));$rows=b_data($k,$r)['items'];d2_parity($rows,d2_read($k,array('include_partials'=>'true'),$p)['items']);d2_assert(count($rows)>0&&$rows[0]['attempt_state']==='PARTIAL_SAVED');$none=b_ready($k,b_create($k,$p));d2_assert(b_data($k,$none)['items']===array());});
b_case('M8 upgrade from 18 creates all export tables and is idempotent without scientific writes',function(){$s=new A\Store();$ids=implode(',',array_map(function($id)use($s){return$s->prepare('%s',$id);},$GLOBALS['ownedKeys']));$foreign=$s->row('SELECT COUNT(*) n FROM '.$s->table('exports').' WHERE key_id NOT IN ('.$ids.')');d2_assert((int)$foreign['n']===0,'Cannot reset nonfixture infrastructure');$db=pf_db();$before=hash('sha256',json_encode($db->rows('SELECT id,checkpoint_hash,revision FROM '.$db->table('study_executions').' ORDER BY id')));foreach(array('export_chunks','export_sources','exports')as$t)$s->rows('DROP TABLE '.$s->table($t));update_option('eipsi_migration_version',18);$runner=new EIPSI_Schema_Migration_Runner();$r=$runner->run();d2_assert($r['success']&&(int)get_option('eipsi_migration_version')===EIPSI_Schema_Migration_Runner::LATEST_VERSION);foreach(array_keys(A\ExportSchema::definitions())as$slug)d2_assert(!EIPSI_Schema_Inspector::inspect($slug)['issues']);d2_assert($runner->run()['success']);$after=hash('sha256',json_encode($db->rows('SELECT id,checkpoint_hash,revision FROM '.$db->table('study_executions').' ORDER BY id')));d2_assert($before===$after);$k=d2_key();$r=b_ready($k,b_create($k));d2_assert(count(b_data($k,$r)['items'])===2);});
